def solve(payload):
    import ipaddress
    if payload["default"] not in ("allow", "deny"):
        return {"error": "invalid_rule"}
    rules = []
    try:
        for rule in payload["rules"]:
            if rule["action"] not in ("allow", "deny"):
                raise ValueError()
            rules.append((ipaddress.ip_network(rule["cidr"], strict=False), rule["action"]))
    except ValueError:
        return {"error": "invalid_rule"}
    decisions = []
    for value in payload["addresses"]:
        try:
            address = ipaddress.ip_address(value)
        except ValueError:
            decisions.append("invalid")
            continue
        result = payload["default"]
        for network, action in rules:
            if network.version == address.version and address in network:
                result = action
                break
        decisions.append(result)
    return {"decisions": decisions}

